from functools import wraps

def retry(times: int):
    def decorate(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except RuntimeError as exc:
                    last_error = exc
            raise last_error
        return wrapper
    return decorate

from queue import Queue
from threading import Thread

queue = Queue()
for value in range(5):
    queue.put(value)

def worker():
    while not queue.empty():
        item = queue.get()
        try:
            print(item * item)
        finally:
            queue.task_done()

